// Attach starter prompts to each assistant.
for (const a of assistants) {
  if (STARTERS[a.id]) a.starters = STARTERS[a.id]
}

export function getAssistant(id: string): Assistant | null {
  return assistants.find((a) => a.id === id) ?? null
}
